#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/mise/tasks/helpers.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Helper functions for Python mise tasks"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}

# The one library that each Python task imports, so all the tasks print in the
# same way. It has the names of the shell library helpers, and each print
# function writes the same bytes as the shell function of the same name. A task
# imports it after it adds the _scripts folder to sys.path:
#
#   sys.dont_write_bytecode = True
#   sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
#   import helpers
#
# Universal: one copy for each repository. Do not edit it in a repository.
# Put a function that only one repository uses in a local sibling file.

import json
import os
import re
import shlex
import subprocess
import sys

# Style
STYLE_BOLD = "\033[1m"
STYLE_ITALIC = "\033[3m"
STYLE_NORMAL = "\033[0m"
# Colors
COLOR_GREEN = "\033[0;32m"
COLOR_YELLOW = "\033[0;33m"
COLOR_RED = "\033[0;31m"

# Shown in front of a message when the output is styled.
EMOJI_SUCCESS = "✅"
EMOJI_WARN = "⚠️"
EMOJI_ERROR = "❌"
EMOJI_INFO = "ℹ️"
EMOJI_HEADER = "🚀"
EMOJI_SUBHEADER = "📌"

# Shown INSTEAD of the emoji when the output is plain. Without them a log file
# loses the type of each line (success, warning or failure), and
# `grep '\[ERROR\]'` finds nothing. A call with no message
# (`print_success()`) prints the label only.
LABEL_SUCCESS = "[OK]"
LABEL_WARN = "[WARN]"
LABEL_ERROR = "[ERROR]"
LABEL_INFO = "[INFO]"

TASKS_DIR = ".config/mise/tasks"

_SIMPLE_ESCAPES = {
  ord("\\"): b"\\",
  ord("a"): b"\a",
  ord("b"): b"\b",
  ord("e"): b"\033",
  ord("E"): b"\033",
  ord("f"): b"\f",
  ord("n"): b"\n",
  ord("r"): b"\r",
  ord("t"): b"\t",
  ord("v"): b"\v",
}
_OCTAL = b"01234567"
_HEX = b"0123456789abcdefABCDEF"


def _expand_escapes(data):
  """Expand the backslash escapes of data (bytes) as printf %b of bash does.

  Returns (bytes, stop). stop is True when data has a \\c escape: the shell
  then stops all output, also the newline after the line.
  """
  out = bytearray()
  i = 0
  n = len(data)
  while i < n:
    c = data[i]
    if c != ord("\\") or i + 1 >= n:
      out.append(c)
      i += 1
      continue
    e = data[i + 1]
    if e in _SIMPLE_ESCAPES:
      out += _SIMPLE_ESCAPES[e]
      i += 2
    elif e == ord("c"):
      return bytes(out), True
    elif e == ord("0"):
      j = i + 2
      while j < n and j < i + 5 and data[j] in _OCTAL:
        j += 1
      out.append(int(data[i + 2 : j] or b"0", 8) & 0xFF)
      i = j
    elif e in _OCTAL:
      j = i + 1
      while j < n and j < i + 4 and data[j] in _OCTAL:
        j += 1
      out.append(int(data[i + 1 : j], 8) & 0xFF)
      i = j
    elif e == ord("x") and i + 2 < n and data[i + 2] in _HEX:
      j = i + 2
      while j < n and j < i + 4 and data[j] in _HEX:
        j += 1
      out.append(int(data[i + 2 : j], 16))
      i = j
    elif e in (ord("u"), ord("U")) and i + 2 < n and data[i + 2] in _HEX:
      digits = 4 if e == ord("u") else 8
      j = i + 2
      while j < n and j < i + 2 + digits and data[j] in _HEX:
        j += 1
      out += chr(int(data[i + 2 : j], 16)).encode("utf-8", "surrogateescape")
      i = j
    else:
      out += data[i : i + 2]
      i += 2
  return bytes(out), False


def _write(file, data):
  """Write the bytes data to file and flush it."""
  file.flush()
  buffer = getattr(file, "buffer", None)
  if buffer is None:
    file.write(data.decode("utf-8", "surrogateescape"))
    file.flush()
    return
  buffer.write(data)
  buffer.flush()


def _join(args):
  """Join the arguments with spaces, as "$*" of the shell does."""
  return " ".join(str(a) for a in args)


def style_enabled(fd=1):
  """Whether the output on the file descriptor fd (default 1) gets styles.

  Decided for each call, not one time at import, because stdout and stderr can
  give different answers: `task > report.txt` keeps stderr on the terminal, so
  print_error stays styled while all of stdout is plain.

    FORCE_COLOR  set (and not `0`) forces the styles on, for CI runners, which
                 show ANSI but never give the task a terminal.
    NO_COLOR     set forces them off (https://no-color.org).
    otherwise    on only when the descriptor is a terminal and TERM is not dumb.
  """
  force = os.environ.get("FORCE_COLOR", "")
  if force and force != "0":
    return True
  if os.environ.get("NO_COLOR", ""):
    return False
  try:
    tty = os.isatty(fd)
  except OSError:
    tty = False
  return tty and os.environ.get("TERM", "dumb") != "dumb"


def _fileno(file):
  """The file descriptor of file, or -1 when it has none."""
  try:
    return file.fileno()
  except (AttributeError, OSError, ValueError):
    return -1


def print_line(file, newline, codes, emoji, label, msg):
  """The one place that makes a line; each printer below calls it.

    file     the stream (sys.stdout or sys.stderr)
    newline  True, or False for a line that the next call completes
    codes    ANSI codes around the message when styled; can be empty
    emoji    prefix when styled; can be empty
    label    prefix when plain; can be empty
    msg      can be empty, then only the prefix shows

  As printf %b of the shell, a `\\n` or `\\t` in a message is interpreted.
  """
  if style_enabled(_fileno(file)):
    mark = emoji
    text = f"{codes}{msg}{STYLE_NORMAL}" if codes and msg else msg
  else:
    mark = label
    text = msg
  out = mark
  if mark and text:
    out += " "
  out += text
  data, stop = _expand_escapes(out.encode("utf-8", "surrogateescape"))
  if newline and not stop:
    data += b"\n"
  _write(file, data)


def _line_sep(pattern="=", file=None):
  """Print a full-width line made of the given pattern.

  Public, but rarely the correct call: print_header and print_subheader below
  already print theirs. Use it directly only for a line with no title after it.
  The width is the width of the terminal on stdin, else 80. The pattern is
  repeated, then cut to the width, so a pattern of more than one character
  never wraps. Keep patterns to single-width characters.
  """
  file = sys.stdout if file is None else file
  try:
    width = os.get_terminal_size(0).columns
  except (OSError, ValueError):
    width = 80
  pattern = pattern or "="
  reps = (width + len(pattern) - 1) // len(pattern)
  line = (pattern * reps)[:width]
  _write(file, f"{line}\n".encode("utf-8", "surrogateescape"))


def line_sep1(file=None):
  """The separator line of print_header."""
  _line_sep("──── ⋆⋅☆⋅⋆ ────", file)


def line_sep2(file=None):
  """The separator line of print_subheader."""
  _line_sep("⋅", file)


def print_header(*msg, file=None):
  """A major section: a full-width line, then the title in green and bold.

  The line is part of the call, so a section never comes without its line.
  """
  file = sys.stdout if file is None else file
  line_sep1(file)
  print_line(file, True, f"{COLOR_GREEN}{STYLE_BOLD}", EMOJI_HEADER, "", _join(msg))


def print_subheader(*msg, file=None):
  """A step in a section: a full-width line, then the title in green.

  Not bold, so a step shows as a part of its section.
  """
  file = sys.stdout if file is None else file
  line_sep2(file)
  print_line(file, True, COLOR_GREEN, EMOJI_SUBHEADER, "", _join(msg))


# A task with one step calls NEITHER. A task that does one thing and prints one
# line does not open a section; the printers below are all that it uses.
#
# The four status printers have one shape: print_success(*msg, bold=False,
# file=None). The message is optional (print_success() prints only the mark),
# and the arguments are joined with spaces.


def print_success(*msg, bold=False, file=None):
  """A success line in green, on stdout."""
  file = sys.stdout if file is None else file
  codes = COLOR_GREEN + (STYLE_BOLD if bold else "")
  print_line(file, True, codes, EMOJI_SUCCESS, LABEL_SUCCESS, _join(msg))


def print_warn(*msg, bold=False, file=None):
  """A warning line in yellow, on stdout."""
  file = sys.stdout if file is None else file
  codes = COLOR_YELLOW + (STYLE_BOLD if bold else "")
  print_line(file, True, codes, EMOJI_WARN, LABEL_WARN, _join(msg))


def print_error(*msg, bold=False, file=None):
  """An error line in red. Errors go to stderr, so a caller that pipes stdout
  into a report still sees them."""
  file = sys.stderr if file is None else file
  codes = COLOR_RED + (STYLE_BOLD if bold else "")
  print_line(file, True, codes, EMOJI_ERROR, LABEL_ERROR, _join(msg))


def print_info(*msg, bold=False, file=None):
  """An info line, on stdout. No color: info is the neutral line, and only bold
  makes it different."""
  file = sys.stdout if file is None else file
  print_line(file, True, STYLE_BOLD if bold else "", EMOJI_INFO, LABEL_INFO, _join(msg))


def print_wait(*msg, file=None):
  """A check on one line: the message in yellow italics with no newline, so the
  status printer that follows completes the line.

    print_wait("Checking docker..."); print_success()

  prints `Checking docker... ✅` on a terminal and `Checking docker... [OK]` in
  a log.
  """
  file = sys.stdout if file is None else file
  print_line(file, False, f"{COLOR_YELLOW}{STYLE_ITALIC}", "", "", _join(msg))


def print_header_wait(*msg, file=None):
  """Kept for the tasks that already call it: green bold text, no newline."""
  file = sys.stdout if file is None else file
  print_line(file, False, f"{COLOR_GREEN}{STYLE_BOLD}", "", "", _join(msg))


def print_yellow(*msg, file=None):
  """Kept for the tasks that already call it: a line in yellow."""
  file = sys.stdout if file is None else file
  print_line(file, True, COLOR_YELLOW, "", "", _join(msg))


def print_newline(file=None):
  """Kept for the tasks that already call it: an empty line."""
  _write(sys.stdout if file is None else file, b"\n")


# The task files are read from the task folder of this repository, never asked
# of mise. In a superproject mise also lists the tasks of the parent, and runs
# a task of the parent in the folder of the PARENT: a submodule that asked
# `mise tasks info setup:ai` finds the task of the root and runs it again.


def _tasks_root():
  return f"{os.environ.get('MISE_PROJECT_ROOT', '')}/{TASKS_DIR}"


def _run_file(path):
  """The file that mise runs for the task file path: path when it exists, else
  path.py."""
  if not os.path.isfile(path) and os.path.isfile(f"{path}.py"):
    return f"{path}.py"
  return path


def has_own_task(name):
  """Whether this repository defines the task name itself, as a file task:
  `setup:ai` is `setup/ai`, or `setup/ai/_default`. For a step that only some
  repositories have, for example `setup:ai` or `setup:external:update`. As mise
  does, it reads `<file>` when it exists, else `<file>.py`.
  """
  path = f"{_tasks_root()}/{name.replace(':', '/')}"
  for file in (path, f"{path}/_default"):
    file = _run_file(file)
    if os.path.isfile(file) and os.access(file, os.X_OK):
      return True
  return False


_PART = re.compile(r"[0-9][0-9]-.+", re.DOTALL)


def own_tasks(group):
  """The tasks that this repository defines in the group (`setup:deps`), as a
  list of names, sorted by file name; empty when it defines none. For a step
  that runs the task of each tool in a group, without the tasks of the parent
  that a wildcard `mise run 'setup:deps:*'` adds. A part is an executable file
  named `NN-<name>` (`40-node`): a folder, `_default` and a file without the
  number are not parts. As mise does, a part `NN-<name>.py` is the task
  `NN-<name>` when no `NN-<name>` exists, else the task `NN-<name>.py`.
  """
  folder = f"{_tasks_root()}/{group.replace(':', '/')}"
  try:
    names = sorted(os.listdir(folder))
  except OSError:
    return []
  tasks = []
  for name in names:
    file = f"{folder}/{name}"
    if not _PART.fullmatch(name) or not os.path.isfile(file) or not os.access(file, os.X_OK):
      continue
    if name.endswith(".py") and not os.path.exists(file[:-3]):
      name = name[:-3]
    tasks.append(f"{group}:{name}")
  return tasks


def tool(*args, **kwargs):
  """Run a tool of mise as `mise x -- <args>` and return the CompletedProcess.
  The keyword arguments go to subprocess.run."""
  return subprocess.run(["mise", "x", "--", *args], check=False, **kwargs)


def has_tool(name):
  """Whether mise finds the tool name (`mise x -- which <name>`)."""
  try:
    result = subprocess.run(
      ["mise", "x", "--", "which", name],
      check=False,
      stdin=subprocess.DEVNULL,
      stdout=subprocess.DEVNULL,
      stderr=subprocess.DEVNULL,
    )
  except OSError:
    return False
  return result.returncode == 0


def bootstrap_get(key, repo=None):
  """The answer of `bootstrap config get <key> --format json` as a dict:
  `{"key": ..., "value": ..., "source": ...}`, with `"contributed_by": [<tool>,
  ...]` when other tools contributed to the value. source is "file",
  "default", "contributed", "derived" or "unselected". Read ["value"]: a key
  that is not set gives its default, or None; a tools.* key gives the value of
  the merge of a sync, and None for a tool that is not selected. key is a key
  of the values in `.config/bootstrap/`, for example `repo.core_branches`; a
  segment with a dot is double-quoted, as in
  `repo.branches."release.1".landing`. With repo, it reads the values of that
  repository instead of this one.

  BOOTSTRAP_BIN, a local build or the engine of a sync, replaces the bootstrap
  of mise. A read failure (code 1) stops the task with code 1, after the
  message of the engine. The task stops with code 2 without an engine that
  answers, for example no bootstrap or one older than 4.0.0, and when the
  engine refuses the read with code 2 and a message, for example a tools.* key
  with no catalog (no --clone, no BOOTSTRAP_CLONE and no cache clone: get
  never fetches), or no .config/bootstrap/. An engine code other than 0 and 1,
  and an answer that is not JSON, also stop it with code 2.
  """
  rc = 0
  answer = None
  binary = ["mise", "x", "--", "bootstrap"]
  if os.environ.get("BOOTSTRAP_BIN", ""):
    binary = [os.environ["BOOTSTRAP_BIN"]]
  elif not has_tool("bootstrap"):
    # mise x answers a missing command with code 1, the code of a read failure.
    rc = 2
  if rc == 0:
    cwd = None
    env = None
    if repo:
      if not os.path.isdir(repo):
        print(f"cd: {repo}: No such file or directory", file=sys.stderr, flush=True)
        sys.exit(1)
      cwd = repo
      env = {k: v for k, v in os.environ.items() if k != "BOOTSTRAP_VALUES"}
      env["MISE_PROJECT_ROOT"] = repo
    try:
      result = subprocess.run(
        [*binary, "config", "get", key, "--format", "json"],
        check=False,
        cwd=cwd,
        env=env,
        stdout=subprocess.PIPE,
        text=True,
      )
      rc = result.returncode
    except (FileNotFoundError, PermissionError):
      rc = 2
    if rc == 0:
      try:
        answer = json.loads(result.stdout)
      except ValueError:
        rc = 2
  if rc == 0:
    return answer
  if rc == 1:
    sys.exit(1)
  where = f" in {repo}" if repo else ""
  print_error(f"bootstrap config get {key} failed{where}.")
  print_warn("- with no bootstrap, or one older than 4.0.0: mise use -g github:virajp/bootstrap", file=sys.stderr)
  print_warn(
    f"- else do the fix of the message above, for example run bootstrap migrate{where}, or bootstrap catalog to"
    " fetch the clone",
    file=sys.stderr,
  )
  sys.exit(2)


def _alt(value, default):
  """The `//` operator of yq: default when value is None or False."""
  return default if value is None or value is False else value


def core_branches(repo=None):
  """The list `core_branches` of `.config/bootstrap/repo.toml`. With repo, the
  list of that repository. It reads the list with bootstrap_get, so it stops
  the task in the same way, and stops it with code 1 when the value is not a
  list.
  """
  value = _alt(bootstrap_get("repo.core_branches", repo).get("value"), [])
  if not isinstance(value, list):
    print_error("cannot read core_branches of .config/bootstrap/repo.toml.")
    sys.exit(1)
  return value


def default_branch(repo=None):
  """The base of each change: `default_branch` of `.config/bootstrap/repo.toml`.
  Without the key, develop when it is a core branch, else main when it is a
  core branch, else the first core branch. With repo, the branch of that
  repository. It stops the task as bootstrap_get does.
  """
  value = bootstrap_get("repo.default_branch", repo).get("value")
  if isinstance(value, str) and value:
    return value
  core = core_branches(repo)
  for name in ("develop", "main"):
    if name in core:
      return name
  return core[0] if core else "main"


def members(repo=None):
  """The members of the repo that are separate repositories: each submodule and
  sibling member of `[members.<name>]` in `.config/bootstrap/repo.toml`, as a
  list of (name, folder, label, url) tuples, in the order of the values.
  folder is relative to the repo root, and the folder of a sibling starts with
  `../`. label is the name when the member has none, and url is empty when
  the member has none. A `folder` member is part of this tree, so it is not in
  the list. With repo, the members of that repository. An empty list when the
  repo has no members.

  It reads the members with bootstrap_get, so it stops the task in the same
  way.
  """
  answer = bootstrap_get("repo.members", repo)
  value = _alt(answer.get("value") if isinstance(answer, dict) else None, {})
  result = []
  for name, member in value.items():
    if not isinstance(member, dict) or member.get("type") not in ("submodule", "sibling"):
      continue
    result.append(
      (
        name,
        _alt(member.get("folder"), name),
        _alt(member.get("label"), name),
        _alt(member.get("url"), ""),
      )
    )
  return result


def gate_files(gate, *args):
  """The files of one code:format or code:lint gate:

    gate_files(<gate file>, [--all], [--debug], [--fix], [<file>...])

  It runs `_scripts/gate_files.py`, which reads the # FILES header of the gate
  file, and returns the path of a temporary file with the list, one path for
  each line; an empty list gives an empty file. The default is the
  uncommitted files of this repository, `--all` each file, and given files
  only those. `--debug` prints each removed file on stderr. The gate deletes
  the file itself. If the script fails, it prints an error and stops the task
  with the code of the script.
  """
  script = f"{_tasks_root()}/_scripts/gate_files.py"
  result = subprocess.run([sys.executable, script, gate, *args], check=False, stdout=subprocess.PIPE, text=True)
  if result.returncode != 0:
    print_error(f"gate_files failed for {gate} with code {result.returncode}.")
    sys.exit(result.returncode)
  return result.stdout.rstrip("\n")


def usage_files():
  """The variadic [files] argument of a gate: mise gives usage_files as shell
  words, so a file name with a space keeps its quotes."""
  return shlex.split(os.environ.get("usage_files", ""))
